it.runIf(process.platform==='win32'&&existsSync(path.join(process.env.SystemDrive||'C:','PROGRA~1')))('expands an actual existing Windows short path with the native physical identity',()=>{
  const short=path.join(process.env.SystemDrive||'C:','PROGRA~1'),expected=realpathSync.native(short),result=qualifyTemporaryEnvironment(short);
  expect(expected).not.toMatch(/~[0-9]/);
  expect(result.canonical).toBe(expected);
  expect(result.environment).toEqual({TMPDIR:expected,TEMP:expected,TMP:expected});
});
